// Move focus between the major regions of the window (editor, open
// panels, status bar). Accessibility navigation; mirrors VS Code's
// "Focus Next/Previous Part". `cmd-f6` mirrors `f6` so region navigation
// stays available even while a debug session rebinds plain `f6` to Pause.
"f6": "workspace::FocusNextPart",
"shift-f6": "workspace::FocusPreviousPart",
"cmd-f6": "workspace::FocusNextPart",
"fn-f": "zed::ToggleFullScreen",
"ctrl-cmd-f": "zed::ToggleFullScreen",
// Change the default action on `menu::Confirm` by setting the parameter
// "alt-cmd-o": ["projects::OpenRecent", {"create_new_window": true }],
"alt-cmd-o": "projects::OpenRecent",
"ctrl-r": "projects::OpenRecent",
"ctrl-cmd-o": ["projects::OpenRemote", { "from_existing_connection": false }],
"ctrl-cmd-shift-o": ["projects::OpenRemote", { "from_existing_connection": true }],
"cmd-ctrl-b": "branches::OpenRecent",
"cmd-ctrl-w": "git::Worktree",
"ctrl-~": "workspace::NewTerminal",
